//! Exporter tests: JSON round trip over every conformance case, and Mermaid / `PlantUML` golden
//! files generated by the Python library (`create_machine(cfg, logic=stub_logic(cfg))`).
#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::fs;
use std::path::{Path, PathBuf};

use serde_json::Value;
use xstate_core::Machine;

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

/// `(file stem, machine config)` for every conformance case.
fn conformance_machines() -> Vec<(String, Value)> {
    let dir = repo_root().join("conformance/cases");
    let mut out = Vec::new();
    for entry in fs::read_dir(&dir).expect("conformance/cases exists") {
        let path = entry.expect("dir entry").path();
        if path.extension().and_then(|e| e.to_str()) != Some("json") {
            continue;
        }
        let doc: Value = serde_json::from_str(&fs::read_to_string(&path).unwrap()).unwrap();
        let stem = path.file_stem().unwrap().to_string_lossy().into_owned();
        out.push((stem, doc["machine"].clone()));
    }
    out.sort_by(|a, b| a.0.cmp(&b.0));
    out
}

/// Trailing whitespace and the final newline are not significant.
fn normalise(text: &str) -> String {
    text.replace("\r\n", "\n").lines().map(str::trim_end).collect::<Vec<_>>().join("\n")
}

#[test]
fn json_round_trips_for_every_conformance_machine() {
    let cases = conformance_machines();
    assert!(cases.len() >= 30, "expected the conformance corpus, found {}", cases.len());
    for (name, config) in cases {
        let machine = Machine::from_value(&config).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(machine.to_json(), config, "{name}: to_json differs from the source");
        let via_config =
            Machine::from_config(xstate_core::config::MachineConfig::from_value(&config).unwrap())
                .unwrap();
        assert_eq!(via_config.to_json(), config, "{name}: from_config lost the source");
        let again = Machine::from_value(&machine.to_json()).unwrap();
        assert_eq!(again.structure_hash(), machine.structure_hash(), "{name}: hash changed");
        assert_eq!(again.to_json(), config, "{name}: second round trip differs");
        let text = machine.to_json_string();
        let reparsed: Value = serde_json::from_str(&text).unwrap();
        assert_eq!(reparsed, config, "{name}: pretty JSON differs");
        assert!(text.contains('\n'), "{name}: to_json_string is not pretty-printed");
    }
}

fn check_golden(extension: &str, render: fn(&Machine) -> String) {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/export");
    let machines = conformance_machines();
    let mut checked = 0;
    for (name, config) in &machines {
        let golden = dir.join(format!("{name}.{extension}"));
        let Ok(expected) = fs::read_to_string(&golden) else { continue };
        let machine = Machine::from_value(config).unwrap();
        assert_eq!(
            normalise(&render(&machine)),
            normalise(&expected),
            "{name}.{extension} differs from the Python output"
        );
        checked += 1;
    }
    assert!(checked >= 4, "expected at least four golden .{extension} files, found {checked}");
}

#[test]
fn mermaid_matches_python_golden_files() {
    check_golden("mmd", Machine::to_mermaid);
}

#[test]
fn plantuml_matches_python_golden_files() {
    check_golden("puml", Machine::to_plantuml);
}

#[test]
fn mermaid_uses_v4_event_names_and_delay_labels() {
    let machine = Machine::from_value(&serde_json::json!({
        "id": "m", "initial": "a",
        "states": {
            "a": {
                "after": { "500": "b", "SLOW": { "target": "b", "guard": "ok" } },
                "invoke": { "src": "svc", "id": "svc",
                            "onDone": "b", "onError": { "target": "c", "guard": "bad" } },
                "always": { "target": "b", "guard": "ready" }
            },
            "b": { "type": "final" },
            "c": {}
        }
    }))
    .unwrap();
    let text = machine.to_mermaid();
    for line in [
        "a --> b : always [ready]",
        "a --> b : after 500ms",
        "a --> b : after SLOW [ok]",
        "a --> b : invoke onDone",
        "a --> c : invoke onError [bad]",
        "b --> [*]",
    ] {
        assert!(text.lines().any(|l| l.trim() == line), "missing `{line}` in:\n{text}");
    }
}
